SELECT array_to_string(array_agg(t.pid), ',') AS id, purchase_org_name, supplier_name, images_url, sku_no, productName, spu_no, avg(tax_price) AS tax_price, round(SUM(orderAmount) / sum(t.purchase_qty)::numeric ,4) AS avgPrice, COUNT(t.id) AS orderQty, SUM(orderAmount) AS orderAmount, max(createTime) AS createTime FROM ( SELECT pod.id AS pid, po.purchase_org_name, pos.supplier_name, pd.images_url, pod.sku_no, pd."name" AS productName, pi.spu_no, pod.tax_price AS tax_price, po.id AS id, pod.purchase_amount AS orderAmount, po.create_time AS createTime, po.purchase_date, pod.purchase_qty FROM purchase_order_detail pod LEFT JOIN purchase_order po ON pod.purchase_order_id = po.id LEFT JOIN purchase_order_supplier pos ON pos.purchase_order_id = po.id LEFT JOIN product_detail pd ON pod.sku_id = pd.id LEFT JOIN product_info pi ON pi.id = pd.product_id WHERE pod.is_deleted = FALSE AND po.approve_status = 'approve' AND po.is_deleted = FALSE AND pos.is_deleted = FALSE AND pd.is_deleted = FALSE AND pi.is_deleted = FALSE AND po.purchase_date >= #{params.billDateList[0]} AND (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > po.purchase_date
AND pod.sku_no IN
#{item}
AND pi.spu_no IN
#{item}
AND po.delivery_warehouse_id in
#{item}
AND po.purchase_org_id in
#{item}
AND pos.supplier_id in
#{item}
)t GROUP BY purchase_org_name, supplier_name, images_url, sku_no, productName, spu_no ORDER BY purchase_org_name, supplier_name, createTime DESC

SELECT id, purchase_org_name, supplier_name, images_url, sku_no, productName, spu_no, tax_price, avgPrice, orderQty, orderAmount, createTime FROM ( SELECT array_to_string(array_agg(t.pid), ',') AS id, purchase_org_name, supplier_name, images_url, sku_no, productName, spu_no, avg(tax_price) AS tax_price, round(SUM(orderAmount) / sum(t.purchase_qty)::numeric ,4) AS avgPrice, COUNT(t.id) AS orderQty, SUM(orderAmount) AS orderAmount, max(createTime) AS createTime FROM ( SELECT pod.id AS pid, po.purchase_org_name, pos.supplier_name, pd.images_url, pod.sku_no, pd."name" AS productName, pi.spu_no, pod.tax_price AS tax_price, po.id AS id, pod.purchase_amount AS orderAmount, po.create_time AS createTime, po.purchase_date, pod.purchase_qty FROM purchase_order_detail pod LEFT JOIN purchase_order po ON pod.purchase_order_id = po.id LEFT JOIN purchase_order_supplier pos ON pos.purchase_order_id = po.id LEFT JOIN product_detail pd ON pod.sku_id = pd.id LEFT JOIN product_info pi ON pi.id = pd.product_id WHERE pod.is_deleted = FALSE AND po.approve_status = 'approve' AND po.is_deleted = FALSE AND pos.is_deleted = FALSE AND pd.is_deleted = FALSE AND pi.is_deleted = FALSE AND po.purchase_date >= #{params.billDateList[0]} AND (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > po.purchase_date
AND pod.sku_no IN
#{item}
AND pi.spu_no IN
#{item}
AND po.delivery_warehouse_id in
#{item}
AND po.purchase_org_id in
#{item}
AND pos.supplier_id in
#{item}
)t WHERE 1 = 1 GROUP BY purchase_org_name, supplier_name, images_url, sku_no, productName, spu_no )tt WHERE 1 = 1
AND tt.id in
#{id}
ORDER BY purchase_org_name, supplier_name, createTime DESC

SELECT t.purchase_org_name AS purchaseOrgName, t.supplier_name AS supplierName, t.images_url AS imagesUrl, t.productName, t.spu_no AS spuNo, t.sku_no AS skuNo, sum(t.orderQty) AS orderQty, sum(t.orderAmount) AS orderAmount, round(CASE WHEN sum(t.orderAmount) = 0 THEN NULL ELSE sum(t.orderAmount) END / sum(t.purchaseQty)::numeric ,4) AS avgPrice, sum(t.receiveQty) AS receiveQty, sum(t.receiveGiftQty) AS receiveGiftQty, sum(t.receiveAmount) AS receiveAmount, sum(t.stockInQty) AS stockInQty, sum(t.stockInGiftQty) AS stockInGiftQty, sum(t.stockInAmount) AS stockInAmount, sum(t.refundQty) AS refundQty, sum(t.replenishQty) AS replenishQty, sum(t.returnAmount) AS returnAmount, MAX(createTime) AS createTime FROM( SELECT po.purchase_org_name, pos.supplier_name, pd.images_url, pd."name" AS productName, pi.spu_no, pd.sku_no, count(po.id) AS orderQty, sum(pod.purchase_amount) AS orderAmount, sum(pod.purchase_qty) AS purchaseQty, 0 AS receiveQty, 0 AS receiveGiftQty, 0 AS receiveAmount, 0 as stockInQty, 0 as stockInGiftQty, 0 AS stockInAmount, 0 as refundQty, 0 as replenishQty, 0 AS returnAmount, MAX(po.create_time) AS createTime FROM purchase_order_detail pod LEFT JOIN purchase_order po ON pod.purchase_order_id = po.id AND po.is_deleted = FALSE LEFT JOIN purchase_order_supplier pos ON pos.purchase_order_id = po.id AND pos.is_deleted = FALSE LEFT JOIN product_detail pd ON pod.sku_id = pd.id LEFT JOIN product_info pi ON pi.id = pd.product_id WHERE pod.is_deleted = FALSE AND po.approve_status = 'approve'
AND po.purchase_date >= #{params.billDateList[0]} AND (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > po.purchase_date
AND pod.sku_no IN
#{item}
AND pi.spu_no IN
#{item}
AND po.delivery_warehouse_id in
#{item}
AND po.purchase_org_id in
#{item}
AND pos.supplier_id in
#{item}
GROUP BY po.purchase_org_name, pos.supplier_name, pd.images_url, pd."name", pi.spu_no, pd.sku_no UNION ALL
SELECT po.purchase_org_name, pos.supplier_name, pd.images_url, pd."name" AS productName, pi.spu_no, pd.sku_no, 0 AS orderQty, 0 AS orderAmount, 0 AS purchaseQty, prd.receive_qty as receiveQty, prd.exceed_qty as receiveGiftQty, round(prd.receive_qty * pod.tax_price::numeric ,4) AS receiveAmount, 0 as stockInQty, 0 as stockInGiftQty, 0 AS stockInAmount, 0 as refundQty, 0 as replenishQty, 0 AS returnAmount, pr.create_time AS createTime FROM po_receive_detail prd LEFT JOIN po_receive pr ON prd.main_id = pr."id" AND pr.is_deleted = FALSE LEFT JOIN purchase_order po ON pr.purchase_order_id = po.id AND po.is_deleted = FALSE LEFT JOIN purchase_order_detail pod ON pod.id = prd.purchase_order_detail_id AND pod.is_deleted = FALSE LEFT JOIN purchase_order_supplier pos ON pos.purchase_order_id = po.id AND pos.is_deleted = FALSE LEFT JOIN product_detail pd ON prd.sku_id = pd.id LEFT JOIN product_info pi ON pi.id = pd.product_id WHERE prd.is_deleted = FALSE AND pr.approve_status = 'approve' AND pr.bill_date >= #{params.billDateList[0]} AND (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > pr.bill_date
AND pod.sku_no IN
#{item}
AND pi.spu_no IN
#{item}
AND po.delivery_warehouse_id in
#{item}
AND po.purchase_org_id in
#{item}
AND pos.supplier_id in
#{item}
UNION ALL
SELECT po.purchase_org_name, pos.supplier_name, pd.images_url, pd."name" AS productName, pi.spu_no, pd.sku_no, 0 AS orderQty, 0 AS orderAmount, 0 AS purchaseQty, 0 AS receiveQty, 0 AS receiveGiftQty, 0 AS receiveAmount, pid.stock_in_qty as stockInQty, pid.exceed_qty as stockInGiftQty, round(pid.stock_in_qty * pod.tax_price::numeric ,4) AS stockInAmount, 0 as refundQty, 0 as replenishQty, 0 AS returnAmount, pit.create_time AS createTime FROM po_instock_detail pid LEFT JOIN po_instock pit ON pid.main_id = pit."id" AND pid.is_deleted = FALSE LEFT JOIN purchase_order po ON pit.purchase_order_id = po.id AND po.is_deleted = FALSE LEFT JOIN purchase_order_detail pod ON pod.id = pid.purchase_order_detail_id AND pod.is_deleted = FALSE LEFT JOIN purchase_order_supplier pos ON pos.purchase_order_id = po.id AND pos.is_deleted = FALSE LEFT JOIN product_detail pd ON pid.sku_id = pd.id LEFT JOIN product_info pi ON pi.id = pd.product_id WHERE pid.is_deleted = FALSE AND pit.approve_status = 'approve'
AND pit.stock_in_date >= #{params.billDateList[0]} AND (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > pit.stock_in_date
AND pod.sku_no IN
#{item}
AND pi.spu_no IN
