SELECT po.purchase_org_name, pos.supplier_name, pd.images_url, pd."name" AS productName, pi.spu_no, pd.sku_no, 0 AS orderQty, 0 AS orderAmount, 0 AS purchaseQty, 0 AS receiveQty, 0 AS receiveGiftQty, 0 AS receiveAmount, 0 as stockInQty, 0 as stockInGiftQty, 0 AS stockInAmount, prd.deduct_amount_qty as refundQty, prd.replenish_qty as replenishQty, 0 AS returnAmount, pr.create_time AS createTime FROM po_return_detail prd LEFT JOIN po_return pr ON prd.main_id = pr."id" AND pr.is_deleted = FALSE LEFT JOIN purchase_order po ON pr.purchase_order_id = po.id AND po.is_deleted = FALSE LEFT JOIN purchase_order_detail pod ON pod.id = prd.purchase_order_detail_id AND pod.is_deleted = FALSE LEFT JOIN purchase_order_supplier pos ON pos.purchase_order_id = po.id AND pos.is_deleted = FALSE LEFT JOIN product_detail pd ON prd.sku_id = pd.id LEFT JOIN product_info pi ON pi.id = pd.product_id WHERE prd.is_deleted = FALSE AND pr.approve_status = 'approve' AND pr.bill_date >= #{params.billDateList[0]} AND (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > pr.bill_date
AND pod.sku_no IN
#{item}
AND pi.spu_no IN
#{item}
AND po.delivery_warehouse_id in
#{item}
AND po.purchase_org_id in
#{item}
AND pos.supplier_id in
#{item}
) t group by t.purchase_org_name, t.supplier_name, t.images_url, t.productName, t.spu_no, t.sku_no ORDER BY
${item.field} ${item.sort}
purchase_org_name, supplier_name, createTime DESC
